      "title": "can_fault_injection_quick_guide",
      "file_type": "docx",
      "chunk_index": 0,
      "text": "CAN Fault Injection Quick Guide\n目的: fault injection の準備、注入条件、観測ポイント、復帰手順を 2 ページ弱の参照用に圧縮する。\n1. Injection families\n2. Decision flow\n3. Notes that often matter\n- trigger condition をログ時刻と同じ粒度で残す。ready後なのか precharge中なのかで意味が変わる。\n- reset 手順を fault 毎に固定しない。bus off clear と full ignition cycle は重みが違う。\n- inject 成功だけで満足しない。fallback path が期待通り単調に進むかを見る。",
