      "id": 21,
      "chunk_ref": "DOC-009-C010",
      "document_ref": "DOC-009",
      "source_label": "pdf\\jmaab_plant_modeling_workshop_6.pdf",
      "source_url": "file:///C:/Users/Kaoru/Documents/RAG_Engine/hils_rag_sample_docs/pdf/jmaab_plant_modeling_workshop_6.pdf",
      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 10,
      "text": "経験を持つと同時に目的意識をも\nった企業人で構成されている。このため、同じプラントモデルを考える際、さまざまなアイデアやデザインがもたらせる。それぞれのモデ\nル作成方法には長所短所があり、正解も不正解もない。他の企業のモデルを見ることは刺激になり、情報や悩みを共有すること\nで、企業を超えた技術の絆が生まれ、絞られた方向性が見えてくる。このように PMWS で得た方向性をまとめてみると、将来、複\n数の会社にまたがって作成する大規模モデル構築する際には、様々なモデリング方法を俯瞰しておくことは、非常に有益であること\nが分かると同時に、今までの書籍では扱われていない内容となっている。このため、ワークショップ内に限らず、多くの技術者や今後\nも出るベース開発の担い手となる学生にも役に立つようにしたいという考えから、本書を作り情報公開することにした。ただし、\nPMWS についてはいろいろな論議をしてきたため、情報も広範囲に渡る。ここ 3 年に絞ってみると、特に以下の３つの項目につい\nて論議を重ねてきた、1 つはプラントモデリングに関する人財育成、２つめはプラントモデルの標準化、３つめはプラントモデルを組\n織間で有効活用することについてである。\nこれらの内容を大きく２部に分け、１および２項目については初級や中級技術者の育成向けに『Simscape によるプラントモ\nデル入門』とし、２および３項目を中心とした内容は、中級や上級技術者向けに『Simscape 実用』と区分けすることとした。\n本書は、前者の入門書としてまとめたものであるが、技術者全般が誤解しやすいことや陥りやすい盲点についても配慮している\nため、上級技術者にも有益な内容となっている。\n1.2 本書の範囲\n現状、MATLAB®/Simulink® 関連書籍は多数出版されており、基礎的な使い方については十分習得できる。しかしなが",
