      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 12,
      "text": "制御ワークショップと連携し、制御可能なモデルとして結合を始めているが、本書を編集し\nている現時点では、制御と結合を行った実績がないことを予め述べておく。\n1。3 本書の公開にあたり\n今回、PMWS のこれまでの内容をまとめ、その成果を公開することにより、様々な現場でモデル作成やシミュレーションを用いた\n開発効率の向上に役立つことを願っている。本書としてまとめられたのは、現在の PMWS のメンバーの努力はもちろんのこと、今\nまで PMWS に属していた方の情報も大いに参考になった。この場でお礼を申し上げる。\nなお、読者にお願いしたいのは、我々は非営利で、他の技術者のお役に立てるよう努力してきた。しかし、一方的な情報開示\nであるため、皆様の意見を測り知ることができない。このため、ぜひ、この入門書を手にして感じたことがあれば、一報頂ければ幸い\nである。\n最後に、PMWS で論議する場、また、Simscape を使って技術情報を共有して頂いた MathWorks® 社に感謝する。\n1.4 著作権\n・本書の著作権は JMAAB に帰属する。\n・JMAAB は、本書の内容に関し、いかなる保証もするものではない。万一本書を利用して不具合等があった場合でも、\nJMAAB は一切責任を負わない。また、本書に記載されている事項は予告なしに変更または廃止されることがあることを理解し、\n活用いただきたい。\n1.5 本書の取り扱い\n・本書は、非営利目的、または利用者内部で使用する場合に限り、複製を可能とする。\n・また、本書を引用する場合は、本書からの引用であることを明示し、引用された著作物の題号や著作者名を明示する等の引\n用の要件を満たす必要がある。\n1.6 内容に関する問い合わせ先\n本書に関する質問やご意見は、JMAAB 事務局（jmaab-office@mathworks.co.jp）に問い合",
