      "text": "くても）プラントモデルが作成できるようになってきた。一方で、制御システムを実装する際は、マイコンの固定小数点演算を\n使うのは変わっていない。アセンブラをやっていた者は、コンピュータはどのように演算するかを熟知している。このため、0.1 は 2 進\n数では表せないことや、メモリ配置の正順を知ってプログラムを組むためモデルベースを使ってもこの点に関しては慎重になる。また、\nSimscape をいきなり使ってしまうと、電子回路を CAD のように組み合わせるだけで、微分方程式を全く意識しなくなってしま\nう。\n例えば、図 2-4 の Simscape モデルと図 2-3 の Simulink モデルが等価であることが分からなくても扱えてしまう。これで\nは、シミュレーションはできても、不具合が出たときにその意味が理解できず、デバックすることができない状態になってしまう。\nこのため、本書を使ってモデルベースを始めることはお勧めしない、Simulink で簡易なプラントモデルを経験したのちに、本書を\n利用することをお勧めする。\nFig.2-3  Simulink モデル (一例)\n10\nJMAAB Plant Model Workshop 6\n2.3.3 Simulink との違い [1-1]\nSimscape がリリースされるまでは、一般的なモデリング環境である Simulink が制御モデルの作成やプラントモデリングに\n用いられてきた。しかしながら、Simulink のソルバーは基本的に常微分方程式を対象とするため、一般的に、微分代数方程\n式で表現される物理システムをモデル化するには、モデル作成者があらかじめシステムを大幅に単純化しなければならない場合\nがある。モデル化の対象が比較的小規模なシステムや、大規模であっても物理的には単純なシステムの場合には問題は無い\nかもしれないが、大規",
