      "file_type": "pdf",
      "chunk_index": 18,
      "text": "6\n【参考文献】\n[1-1] プラントモデリングのための MuPAD® 入門 (一部抜粋), JMAAB Plant Modeling Workshop 3\n12\nJMAAB Plant Model Workshop 6\n3 簡易 HEV パワートレーンモデル\n3.1 目的\n既述している JMAAB のプラントモデルワークショップにおいて、各メンバーの Simscape の理解、スキルアップを図るためハイ\nブリッドエレクトリックビークル（Hybrid Electric Vehicle 以下 HEV）のパワートレーンを題材として、Simscape のサンプルモ\nデルを作成した。本章では、そのモデルを取り上げ、Simscape でプラントモデルを構築した場合における各コンポーネント間の接\n続性や可読性や、Simscape の利点である各コンポーネントを自由に配置し、各種のパワートレーンを簡単に構築出来ることを\n解説する。あわせて、HEV パワートレーンモデルで使用している各コンポーネントを Simscape Language で作成したものを\n解説するので、Simscape によるプラントモデリング手法の参考としてほしい。また、本モデルは、第 4 章の車両運動モデルと接\n続し車両全体モデルとしての接続性検証や、モデルアーキテクチャ検討用としても利用した。\n3.2 Simscape による HEV モデル構成例\n一言で HEV といっても、メーカ各社が様々なパワートレーン方式を開発、製品化している。これら様々な HEV パワートレーン\n方式を、Simscape で作成した個々のコンポーネントモデルを組み合わせることで、シミュレーションモデルの構築が容易に可能と\nなる。以下の図は、PMWS の各メンバーが作成したコンポーネントを持ち寄り、構築した HEV モデルの一例であるが、トル",
