      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 19,
      "text": "ーネントモデルを組み合わせることで、シミュレーションモデルの構築が容易に可能と\nなる。以下の図は、PMWS の各メンバーが作成したコンポーネントを持ち寄り、構築した HEV モデルの一例であるが、トルクコン\nバータの前にエンジンによる発電用モータ、トルクコンバータ後に走行用モータを配置した 2 モータ HEV 方式の場合のシステム図\nである。\nFig.3-1  HEV システム (一例)\nEngine Torque\nConverter\nT/M Differential\nGear\nTire\nVehicle\nLoad\nGenerator Motor\nDriver Acceleration Pedal Position\nBrake Pedal Position\nEngine\nController\nT/M\nController\nPT System\nController\nmechanical.rotational domain\nelectrical domain\nMot/Gen\nController\nTorque Request\nBattery\nManagement\nTorque Request Gear Request\nCharged RatePlant Model(Simscape)\nController Model(Simulink)\nBattery\n13\nJMAAB Plant Model Workshop 6\n上記システムのプラントモデル部分を Simscape でモデル化した場合は、以下の図の通りとなる。もちろん、モータを一つ削除\nすれば、1 モータタイプの HEV モデルに変更することも容易である。尚、以下のモデル図中で緑線は機械・回転系の物理ドメイ\nン信号を示しており、青線は電気の物理ドメインの信号を表示している。\nFig.3-2  Simscape による HEV",
