      "file_type": "pdf",
      "chunk_index": 20,
      "text": "変更することも容易である。尚、以下のモデル図中で緑線は機械・回転系の物理ドメイ\nン信号を示しており、青線は電気の物理ドメインの信号を表示している。\nFig.3-2  Simscape による HEV モデル（一例）\n14\nJMAAB Plant Model Workshop 6\nまた、別の HEV パワートレーン方式として、トランスミッションの代わりにプラネタリギヤを使用した HEV 方式についても簡単に説\n明する。前述のモデルから、トルクコンバータとトランスミッションモデルを削除し、プラネタリギヤモデルを追加して、物理ドメインを接\n続するだけで済むことが、次の図からお分かりいただけると思う。\n以上の通り、今回紹介したサンプルモデルは、Simscape 標準の機械・回転ドメインと電気ドメインだけを使用した単純なモデ\nルであるが、Simulink で作られたプラントモデルに対して、実際のコンポーネントを組み立てる感覚で接続していくため、非常に操\n作性がよく、複雑な結線が無くシンプルなため可読性も良い。また、同一のドメイン同士の信号線を接続するだけで済むため、人\nFig.3-3  プラネタリギヤを使用した HEV システム\nEngine Differential\nGear\nTire\nVehicle\nLoad\nMotor\nDriver Acceleration Pedal Position\nBrake Pedal Position\nEngine\nController\nPT System\nController\nmechanical.rotational domain\nelectrical domain\nMot/Gen\nController\nTorque Request\nBattery\nManagement\nTorque Request\nCharged Rate\nPlant Mode",
