      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 21,
      "text": "l domain\nMot/Gen\nController\nTorque Request\nBattery\nManagement\nTorque Request\nCharged Rate\nPlant Model(Simscape)\nController Model(Simulink)\nPlanetary\nGear\nGenerator Battery\nFig.3-4  Simscape によるプラネタリギヤを使用した HEV モデル\n15\nJMAAB Plant Model Workshop 6\n為的なミスが起こりにくい。最終的には、Simscape で作成したプラントモデルは、Simulink プラットフォーム上で、Simulink で\n作成したコントローラモデルとシームレスに接続し、シミュレーションできることが最大の利点である。\n16\nJMAAB Plant Model Workshop 6\n3.3 部品モデル\n本章では、HEV パワートレーンモデルで使用している、Simscape Language で作成した各コンポーネントモデルを簡単に説\n明する。\n3.3.1 エンジン\nコントローラから出力されるトルク指示値に基づき、エンジン回転数に応じてあらかじめ設定された最大エンジントルクの範囲内\nで、エンジントルクを出力する簡易モデルとなる。尚、エンジントルクの応答遅れ、エンジン回転慣性などは考慮されていない。\nエンジン最大トルク𝑇𝑒_𝑚𝑎𝑥は、以下の通りエンジン回転数𝑊応じた 1D テーブルで設定する。\n𝑇𝑒_𝑚𝑎𝑥 =  𝐹(𝑊)\nテーブル内部：線形補間（interp_method=1）\nテーブル外部：最終値保持(extrap_method=2)：\nエンジン出力トルク𝑡は、コントローラからの要求トルク𝑇_𝑑𝑒𝑚𝑎𝑛𝑑と上記最大トルク𝑇𝑒_𝑚𝑎𝑥を比較して以下の通り出力される。\n𝑇𝑒",
