      "text": "）\nテーブル外部：最終値保持(extrap_method=2)：\nエンジン出力トルク𝑡は、コントローラからの要求トルク𝑇_𝑑𝑒𝑚𝑎𝑛𝑑と上記最大トルク𝑇𝑒_𝑚𝑎𝑥を比較して以下の通り出力される。\n𝑇𝑒𝑚𝑎𝑥 ≧  𝑇𝑒_𝑑𝑒𝑚𝑎𝑛𝑑  のとき、\n𝑡 =  𝑇𝑒_𝑑𝑒𝑚𝑎𝑛𝑑\n𝑇𝑒𝑚𝑎𝑥 <  𝑇𝑒_𝑑𝑒𝑚𝑎𝑛𝑑  のとき、\n𝑡 =  𝑇𝑒_𝑚𝑎𝑥\n（１）モデルブロック\nFig.3-5  エンジンブロック\n17\nJMAAB Plant Model Workshop 6\n（２）接続例\n（３）モデル詳細\n名称 Engine\n概要 エンジン最大トルクの範囲内で、指示されたエンジントルクを出力\nトルクの向き；ノード c to r\n計算内容；\n①エンジン回転数に応じてエンジン最大トルクを算出\n②要求トルクがエンジン最大トルクの範囲内であれば、要求トルクを軸トルクとして出力\n③要求トルクがエンジン最大トルクを超えている場合は、最大トルクを軸トルクとして出力\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 r 機械回転 トルク(Nm),\n回転数(rad/s)\nエンジン出力\n(パワートレーン)\nright\n2 c 機械回転 トルク(Nm),\n回転数(rad/s)\n入力\n(メカニカルリファレンス)\nleft\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 R 要求トルク - 0 N*m left\n出力   ポート名 内容 範囲 初期値 単位 表示位置\n1 Tmax エンジン最大ト\nルク\n- 0 N*m right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 x_t X;エンジン回\n転数\n- 外部テーブル(下\n記参照)\nrpm\n2 y_t Y;エンジン最\n大トルク\n- 外部テーブル(下\n記参照)\nN*m\n変数   変数名 内容",
