      "text": "範囲 初期設定値 単位\n1 x_t X;エンジン回\n転数\n- 外部テーブル(下\n記参照)\nrpm\n2 y_t Y;エンジン最\n大トルク\n- 外部テーブル(下\n記参照)\nN*m\n変数   変数名 内容 範囲 初期値 単位\nFig.3-6  エンジンブロック 接続例\n18\nJMAAB Plant Model Workshop 6\n1 t エンジン出力ト\nルク\n- 0 N*m\n2 w エンジン角速\n度\n- 0 rad/s\n方程式、その他\n①下記テーブルよりエンジン最大トルクを算出\ntmax\n[エンジン最大トルクテーブル]\nx_t\n(rpm)\n0 500 1000 2000 3000 4000\ny_t\n(N*m)\n200 400 400 400 400 400\n②要求トルクがエンジン最大トルクの範囲内であれば、要求トルクを軸トルクとして出力\ntmax > TrqRq  のとき t = TrqRq\n③要求トルクがエンジン最大トルクを超えている場合は、最大トルクを軸トルクとして出力\ntmax ＜ TrqRq  のとき t = tmax\n19\nJMAAB Plant Model Workshop 6\n（３）Simscape コード\ncomponent Engine % Simple Engine % Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop        parameters(Size = variable)         Rev    = { [  0 500 1000 2000 3000 4000], 'rpm' };    % Vector of engine speed         Torque = { [200 400  400  400  400  400], 'N*m' };    % Vector",
