      "text": "trapolation=nearest);             else                 assert(0, 'invalid extrapolation method');                 Te_max == 0;             end           else             assert(0, 'invalid interpolation method');             Te_max == 0;         end           if (Te_demand > Te_max)             Te == Te_max;         else             Te == Te_demand;         end     end end\nエンジン出力トルク計算\n最大トルクの 1D テーブル\n補間計算\n20\nJMAAB Plant Model Workshop 6\n3.3.2 モータ\nコントローラからのモータ指示トルクに応じて、トルクを出力する簡易モータモデルとなる。モータ損失は、効率により簡易的に考\n慮している。また、モータ電流制限に応じて出力トルクを制限する。\nコントローラからの目標モータトルク 𝑇_𝑡𝑎𝑟𝑔𝑒𝑡(𝑇𝑎𝑟𝑔𝑒_𝑇𝑜𝑟𝑞𝑢𝑒)に対して、モータが消費、もしくは発電する電流𝐼_𝑡𝑒𝑚𝑝 を求\nめる。\nモータを力行側（正モータトルク）で使用する場合、\n𝑉 ∗ 𝐼_𝑡𝑒𝑚𝑝∗ 𝐸𝑓𝑓𝑖𝑐𝑖𝑒𝑛𝑐𝑦 =  𝑇_𝑡𝑎𝑟𝑔𝑒𝑡 ∗  𝑊\n𝐼𝑡𝑒𝑚𝑝 =  𝑇_𝑡𝑎𝑟𝑔𝑒𝑡∗  𝑊\n𝑉 ∗ 𝐸𝑓𝑓𝑖𝑐𝑖𝑒𝑛𝑐𝑦\nモータを充電側（負モータトルク）で使用する場合、\n𝑉 ∗ 𝐼_𝑡𝑒𝑚𝑝 =  𝑇_𝑡𝑎𝑟𝑔𝑒𝑡 ∗  𝑊 ∗ 𝐸𝑓𝑓𝑖𝑐𝑖𝑒𝑛𝑐𝑦\n𝐼𝑡𝑒𝑚𝑝 =  𝑇_𝑡𝑎𝑟",
