      "id": 40,
      "chunk_ref": "DOC-009-C029",
      "document_ref": "DOC-009",
      "source_label": "pdf\\jmaab_plant_modeling_workshop_6.pdf",
      "source_url": "file:///C:/Users/Kaoru/Documents/RAG_Engine/hils_rag_sample_docs/pdf/jmaab_plant_modeling_workshop_6.pdf",
      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 29,
      "text": "（１）モデルブロック\n（２）接続例\nFig.3-7  モータブロック\nFig.3-8  モータブロック 接続例\n22\nJMAAB Plant Model Workshop 6\n（３）モデル詳細\n名称 Motor\n概要 HEV コントローラからのモータ指示トルクに応じて、トルクを出力\n電流の向き；モータで消費する電流を正\nトルクの向き；車両を前進させる時のモータトルクを正\n①エネルギ保存則； 電気エネルギー（電圧、電流） ⇔ 回転運動エネルギー（回転速度、トルク）\n②モータ効率のみ考慮(フリクションは未考慮)\n③モータ定格電流を制限するため（本来は Inverter で行う）、ターゲットトルクから電流制限値に応じて出力\nトルクを制限\nノード   ポート名 物理ドメイン Through/Across 内容（接続先） 表示位置\n1 p(+) 電気 電圧（V）、電流（A） モータ入力側正極\n(Battery＋)\nleft\n2 n(-) 電気 電圧（V）、電流（A） モータ入力側負極\n(Battery－)\nleft\n3 R 機械回転 回転数(rad/s)、トルク(Nm) モータ出力\n(パワートレーン)\nright\n4 C 機械回転 回転数(rad/s)、トルク(Nm) 入力\n(メカニカルリファレンス)\nright\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 Target\nTorque\n指示トルク - 0 N*m right\nパラメータ   ポート名 内容 範囲 初期値 単位\n1 EMeff モータ効率 0 ..1 0.9 1\n2 Ilim 電流制限 >0 300 A\n変数   変数名 内容 範囲 初期値 単位\n1 i 電流 - 0(High) A\n2 i_temp ターゲットトル\nクからの電流\n- 0 A\n3 v 電圧 - 0 V\n4 t モータ出力ト\nルク\n- 0",
