      "file_type": "pdf",
      "chunk_index": 30,
      "text": "数   変数名 内容 範囲 初期値 単位\n1 i 電流 - 0(High) A\n2 i_temp ターゲットトル\nクからの電流\n- 0 A\n3 v 電圧 - 0 V\n4 t モータ出力ト\nルク\n- 0 N*m\n5 w モータ角速度 - 0 rad/sec\n方程式、その他\nターゲットモータトルク(正)に必要な電流\nI_temp = T_target * W  / ( V * Efficiency)\nターゲットモータトルク(負)に必要な電流\nI_temp = T_target * W  *Efficiency / V\n23\nJMAAB Plant Model Workshop 6\nモータ出力トルクを電流上限に応じて制限\n① 0≦ I_temp| < I_max の時\nT = T_target                                     ,   I  =T_target * W / ( V * Efficiency)\n② I_temp >= I_max の時\nT = (V * I_max * Efficiency) / W   ,   I = I_max\n③ -I_max I_ < temp  <0 の時\nT = T_target                                     ,   I  =T_target * W  * Efficiency /  V\n④ -I_temp  ≦ -I_max の時\nT = (V * -I_max * Efficiency) / W , I = -I_max\n電位差\nV   =  p.v - n.v\nモータ回転数\nW  =  R.w - C.w\n（４）Simscape コード\ncomponent Motor\n% Simple Motor\n% Motor with max current\npar",
