      "text": "% Torque\nW      = { 0, 'rad/s' };    % Angular velocity\nend\nbranches\nI : p.i -> n.i;\nT : C.t -> R.t;\nend\n24\nJMAAB Plant Model Workshop 6\nequations\nV ==  p.v - n.v;\nW ==  R.w - C.w;\nif (T_target >= 0)\nV * I_temp * Efficiency == T_target * W;\nelse %T_target < 0\nV * I_temp  == T_target * W * Efficiency;\nend\nif (I_temp < I_max && I_temp >= 0)\nT == T_target;\nI == T_target / V / Efficiency * W;\nelseif (I_temp >= I_max)\nT == V * I_max * Efficiency / W;\nI == I_max;\nelseif(I_temp > -I_max && I_temp < 0)\nT == T_target;\nI == T_target / V * Efficiency * W;\nelse %I_temp <= -I_max\nT == V * (-I_max) / Efficiency / W;\nI == -I_max;\nend\nend\nend\nモータ正トルク、モータは電流を消費する場合の\nmechanical、electrical との関係式。\n電流制限値による正負モータトルクのリミット。\nモータ負トルク、モータは発電する場合の\nmechanical、electrical との関係式。\n25\nJMAAB Plant Model Workshop 6\n3.3.3",
