      "text": "モータトルクのリミット。\nモータ負トルク、モータは発電する場合の\nmechanical、electrical との関係式。\n25\nJMAAB Plant Model Workshop 6\n3.3.3 トルクコンバータ\nトルクコンバータは流体継ぎ手の一種であり、ポンプインペラー（以下インペラー）、タービンランナ（以下タービン）、ステータか\nら構成され、トルク増幅効果を有する。\nインペラーが入力軸、タービンが出力軸にあたり、その回転数の比を速度比と呼ぶ。\nSpeedRatio= W_trb\nW_imp\nここで、\nSpeedRatio:速度比[-], W_trb:タービン回転数[rad/s], W_imp:インペラー回転数[rad/s]\n一般的に、トルクコンバータの性能は、以下の 2 式で表される。\nTorqueRatio = T_trb\nT_imp\nτ = T_imp\nW_imp2\nここで、\nTorqueRatio:トルク比[-], T_trb:タービントルク[Nm],\nW_imp:インペラートルク[Nm], τ:トルク容量係数[Nm/(rad/s)2]\nトルク比、トルク容量係数は、速度比に依存した特性として与えられる。例えばトルク比は、速度比が 0 の場合に最大となり、\n速度比が 1 に近づくにつれて減少していき、速度比 1 近くでは約 1（損失があるため、1 を下回る）となる。本モデルでも、トル\nク比と容量係数を、速度比に依存した値として特性データから補間して計算し、外部から入力値として与えるようにしている。\nまた、容量係数は、様々な係数の取り方があり、本モデルで用いている容量係数 K[(rad/s)/(Nm)-0.5]とτとは下記の関係\nがある。\nτ = 1 − SpeedRatio\nK2\nまた、本モデルはロックアップ機構を有していない。\n26\nJMAAB Plant M",
