      "text": "係数 K[(rad/s)/(Nm)-0.5]とτとは下記の関係\nがある。\nτ = 1 − SpeedRatio\nK2\nまた、本モデルはロックアップ機構を有していない。\n26\nJMAAB Plant Model Workshop 6\n（１）モデルブロック\n（２）接続例\n（３）モデル詳細\n名称 Torque Converter\n概要 トルク増幅効果を模擬する簡単なトルクコンバーターモデル\nトルクの向き； すべてのポートで外から内が正\n計算内容；\n① 入力された容量係数からインペラー負荷トルクを計算（スレッシュホールドによるガードあり）\n② インペラー負荷トルクから、入力されたトルク比をかけてタービン出力トルクを計算\n③ タービン回転数はインペラー回転数に速度比を書けたものになる。（スレッシュホールドによるガードあり）\nFig.3-9  トルクコンバータブロック\nFig.3-10  トルクコンバータブロック 接続例\n27\nJMAAB Plant Model Workshop 6\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 Impeller 機械・回転 トルク(Nm)、回転数\n(rad/s)\nインペラー側出力 left\n2 Turbine 機械・回転 トルク(Nm)、回転数\n(rad/s)\nタービン側出力 right\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 Capacity\nFactor\n容量係数 - 0 (rad/s)/(N*m)^0.5 left\n2 Torque Ratio トルク比 - 0 - left\n出力   ポート名 内容 範囲 初期値 単位 表示位置\n1 SpeedRatio 速度比 - 0 - right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 SpeedRatio_th スレッ",
