      "file_type": "pdf",
      "chunk_index": 35,
      "text": "ート名 内容 範囲 初期値 単位 表示位置\n1 SpeedRatio 速度比 - 0 - right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 SpeedRatio_th スレッシュホー\nルド(速度比)\n0-1 0.97 -\n2 K_th スレッシュホー\nルド(容量係\n数)\n>0 50 (rad/s)/(N*m)^0.5\n3 W_th スレッシュホー\nルド(速度)\n>0 0.1*(2*pi)/60 rad/s\n4\n変数   変数名 内容 範囲 初期値 単位 Port\n1 T_impeller インペラー負\n荷トルク\n- 0 N*m Impeller\n2 T_turbin タービン出力ト\nルク\n- 0 N*m Turbine\n3 W_impeller インペラー速\n度\n- 0 rad/s Impeller\n4 W_turbine タービン速度 - 0 rad/s Turbine\n5\n6\n7\n方程式、その他\nトルクコンバータにおける速度の関係より\nW_turbine==SpeedRatio * W_impeller\n速度比と容量係数を用いてインペラー負荷トルクを計算\nT_impeller == sign( 1 - SpeedRatio ) * ( W_impeller / K )^2\nインペラー負荷トルクからタービン出力トルクを計算\nT_turbine == - T_impeller * TorqueRatio\n28\nJMAAB Plant Model Workshop 6\n（４）Simscape コード\ncomponent TorqueConverter\n% Torque Converter\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nparameters\nSpeedRatio_th =",
