      "chunk_index": 40,
      "text": "倍して、出力軸トルクを算出する\n32\nJMAAB Plant Model Workshop 6\n（４） Simscape コード\ncomponent GearBox\n% Gear Box\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nparameters\nkp = { 1/3e+5, 'N*m/rad'     }; % Base/input angular compliance (kp)\nkv = { 1/0.05, 'N*m/(rad/s)' }; % Base/input angular compliance damping (kv)\nend\ninputs\nRatio = { 2.393, '1' }; % GearRatio : left\nend\nnodes\nR = foundation.mechanical.rotational.rotational;  % R : left\nC = foundation.mechanical.rotational.rotational;  % C : right\nend\nvariables\nT_in  = { 0, 'N*m'   };\nT_out = { 0, 'N*m'   };\nW_in  = { 0, 'rad/s' };\nW_out = { 0, 'rad/s' };\nph    = { 0, 'rad'   }; % Compliance\ndph   = { 0, 'rad/s' };\nend\nfunction setup\nph = 0;\nend\nbranches\nT_in  : R.t -> *;\nT_out : C.t -> *;\nend\nequations\nW_in == R.w;\nW_out == C.w;\ndph == der(ph);\ndp",
