      "text": "ches\nT_in  : R.t -> *;\nT_out : C.t -> *;\nend\nequations\nW_in == R.w;\nW_out == C.w;\ndph == der(ph);\ndph == Ratio*W_out - W_in;\nT_in == -kp*ph - kv*dph;\nT_out == -Ratio*T_in;\nend\nend\nGear Box へ入ってくるトルクを正\n入力トルクをギヤ比倍して、出力トルクとする\n入力トルクは角度差・回転数差から算出する\n33\nJMAAB Plant Model Workshop 6\n3.3.5  プラネタリギヤ\nキャリヤへの入力トルクをサンギヤ・リングギヤに分割して出力する簡易モデルとなる。伝達効率は未考慮である。\n以下にプラネタリギヤモデルについて説明する。\ntc/wc はキャリヤのトルク/回転数である。ts/ws/Zs はサンギヤのトルク/回転数/歯数である。tr/wr/Zr はリングギヤのトル\nク/回転数/歯数である。\nプラネタリギヤのサンギヤ・キャリヤ・リングギヤの回転数の関係は、いずれか 2 つの回転数が決まれば、残る 1 つの回転数は一\n意に決まる。以下の共線図を描くと理解しやすい。\ngr はサンギヤの歯数／リングギヤである。回転数の関係式について、導出方法の一例を以下に示す。青で網掛けした三角形\nの部分の相似の関係から以下の比が得られる。\n1：1 + 𝑔𝑟= (𝑤𝑐 − 𝑤𝑠)：(𝑤𝑟 − 𝑤𝑠)\nwc について解く。\n𝑤𝑐 − 𝑤𝑠 = 𝑤𝑟 − 𝑤𝑠\n1 + 𝑔𝑟\nFig.3-15  プラネタリギヤ共線図  (回転数)\nサンギヤ キャリヤ リングギヤ\n1 gr＝Zs/Zr\nws\nwc\nwr\nwc-ws\nwr-ws\nFig.3-14  プラネタリギヤ\n34\nJMAAB Plant Model W",
