      "chunk_index": 42,
      "text": "ヤ共線図  (回転数)\nサンギヤ キャリヤ リングギヤ\n1 gr＝Zs/Zr\nws\nwc\nwr\nwc-ws\nwr-ws\nFig.3-14  プラネタリギヤ\n34\nJMAAB Plant Model Workshop 6\n𝑤𝑐 = 𝑤𝑟 − 𝑤𝑠\n1 + 𝑔𝑟 + (1+ 𝜌)𝑤𝑠\n1 + 𝑔𝑟\n𝑤𝑐 = 𝑔𝑟\n1+ 𝑔𝑟𝑤𝑠 + 1\n1 + 𝑔𝑟𝑤𝑟\n上式がプラネタリギヤのサンギヤ・キャリヤ・リングギヤの回転数を表す関係式である。\nトルクの関係式も共線図を描くと理解しやすい。\nプラネタリギヤのトルク配分はテコの原理で考えられる。リングギヤを支点と考えると、以下の式が得られる。\n(1 + 𝑔𝑟) ∙ 𝑡𝑆 = 𝑔𝑟∙ 𝑡𝐶\nts について解くと、次のようになる。\n𝑡𝑠 = 𝑔𝑟\n1 + 𝑔𝑟𝑡𝐶\n同様にサンギヤを支点と考えると、次のようになる。\n(1 + 𝑔𝑟) ∙ 𝑡𝑟 = 𝑡𝐶\n更に、tr について解くと、次のように表せる。\n𝑡𝑟 = 1\n1 + 𝑔𝑟𝑡𝐶\nFig.3-16  プラネタリギヤ共線図  (トルク)\nサンギヤ キャリヤ リングギヤ\n1 gr＝Zs/Zr\nts\ntc\ntr\n35\nJMAAB Plant Model Workshop 6\n（１）モデルブロック\n（２）接続例\n（３）モデル詳細\n名称 Planetary Gear\n概要 キャリヤ(入力)トルクを、サンギヤ・リングギヤ(出力)トルクに分割する。\nトルクの向き：車両を前進させる時のトルクを正とする。\n伝達ロスは未考慮。\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 C 機械回転 トルク(Nm),\n回転数(rad/s)\nキャリヤ軸 left\n2 R 機械回転 トルク(Nm),\n回転数(rad/s)\nリングギヤ軸 right\n3 S 機械回転 トルク(Nm),\n回転数(r",
