      "text": "al.rotational.rotational;  % R : right\nS = foundation.mechanical.rotational.rotational;  % S : right\nend\nparameters\nZs = { 1  '1'  };  % Sun gear Teeth Number\nZr ={ 1  '1'  };   % Ring gear Teeth Number\nend\nvariables\ntc  = { 0  'N*m'   };\ntr  = { 0  'N*m'   };\nts  = { 0  'N*m'   };\nwc  = { 0  'rad/s' };\nwr  = { 0  'rad/s' };\nws  = { 0  'rad/s' };\ngr  = { 1  '1' };\nend\nbranches\ntc  : C.t -> *;\nts  : * -> S.t;\ntr  : * -> R.t;\nend\nequations\nwc == C.w;\nws == S.w;\nwr == R.w;\ngr == Zs/Zr;\nts == gr/(1+gr)*tc;\ntr == 1/(1+gr)*tc;\nwc == gr/(1+gr)*ws + 1/(1+gr)*wr;\nend\nキャリヤへの入力を正\nサンギヤ・リングギヤへの出力を正\nキャリヤトルクをサンギヤリングギヤに分割\n38\nJMAAB Plant Model Workshop 6\n3.3.6 ディファレンシャル\n通称デフと呼ばれるディファレンシャルは、自動車がスムーズに曲がるために必要な差動機構である。本モデルは、入力トルクに\n対して左右輪にトルクを分配する挙動を模擬した簡易的なモデルであり、ギヤ効率およびギヤ比はパラメータとして設定できるよう\nにしている。\nFig.3-19 のよう",
