      "text": "_in\nw_in\nt_out1\nw_s1\nLeft wheel Right wheel\nt_out2\nw_s2\nInput gear\nRing gear Pinion gear\nw_p\nSide gear\n39\nJMAAB Plant Model Workshop 6\n（１）モデルブロック\n（２）接続例\n（３）モデル詳細\n名称 Differential Gear\n概要 回転、トルクのみを考慮した単純な Differential Gear モデル\nトルクの向き； すべてのポートで外から内が正\n計算内容；\n① 入力されたパワトレ―ントルから効率分を差し引いて左右輪に分配\n② 左右輪のドライビングトルクの差から、ピニオンギア回転数を計算\n③ ピニオンギア回転数から左右輪の回転数を算出\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 In 機械・回転 トルク(Nm),\n回転数(rad/s)\nパワートレーントルク\n入力\nleft\n2 S1 機械・回転 トルク(Nm),\n回転数(rad/s)\n左(右)輪への出力 right\nFig.3-20  デファレンシャルブロック\nFig.3-21  デファレンシャルブロック 接続例\n40\nJMAAB Plant Model Workshop 6\n3 S2 機械・回転 トルク(Nm),\n回転数(rad/s)\n(左)右輪への出力 right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 Eta デフ効率 0-1 0.9 1\n2 Rin デフギア比 >0 1.33 1\n3 Rps ピニオン/サイドギ\nア比\n>0 1 1\n4 Ip ピニオンギアイナー\nシャ\n>0 0.01 kgm^2\n変数   変数名 内容 範囲 初期値 単位 Port\n1 t_in パワートレーン入\n力トルク\n- 0 Nm In",
