      "text": "ア比\n>0 1 1\n4 Ip ピニオンギアイナー\nシャ\n>0 0.01 kgm^2\n変数   変数名 内容 範囲 初期値 単位 Port\n1 t_in パワートレーン入\n力トルク\n- 0 Nm In\n2 t_out1 左(右)輪への出\n力トルク\n- 0 Nm S1\n3 t_out2 (左)右輪への出\n力トルク\n- 0 Nm S2\n4 w_in デフ入力ギア角\n速度\n- 0 rad/s In\n5 w_s1 左(右)輪角速 - 0 rad/s S1\n6 w_s2 (左)右輪角速 - 0 rad/s S2\n7 w_p ピニオンギア角\n速度\n- 0 rad/s\n方程式、その他\nデフにおけるエネルギ保存則より\nt_out1 + t_out2 + t_in * Eta * Rin = 0\n左右輪のトルク差からピニオンギアの角速度を計算\nw_p.der = Rps / Ip *( t_out1 - t_out2)\nピニオンギア角速度より、左右輪角速度を計算\nw_s1 == 1 / Rin * w_in + Rps * w_p\nw_s2 == 1 / Rin * w_in - Rps * w_p\n41\nJMAAB Plant Model Workshop 6\n（４）Simscape コード\ncomponent DifferentialGear\n% Differential Gear\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nnodes\nIn   = foundation.mechanical.rotational.rotational; % In:left\nOut1 = foundation.mechanical.rotational.rotational; % S1:right\nOut2 = foundation.me",
