      "text": "ight\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 OCV バッテリ開路電圧 0～100 0 V left\n出力   ポート名 内容 範囲 初期値 単位 表示位置\n1 SOC バッテリ充電率 0～100 0 % right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 SOC_init 初期充電率 0～100 60 %\n2 Qmax 最大容量 >0 7*3600 A*s\n3 R 内部抵抗 >=0 0.1 Ω\n変数   変数名 内容 範囲 初期値 単位\n1 Ib 電流 - 0 A\n2 Vb バッテリ電圧 - 0 V\n3 Q_internal 電荷量\n（中間変数）\n- SOC_init/1\n00*Qmax\nA*s\n4 Q_current 電荷量 0～Qmax 0 A*s\n方程式、その他\nFig.3-23  バッテリーブロック接続例\n44\nJMAAB Plant Model Workshop 6\nバッテリ電荷保存（SOC 計算のために電流による電荷量変化量を計算）\nIb + dQ_internal/dt == 0\nQcur と Qin の関係（電荷量（中間変数）を最小値、最大値で制限）\nQ_current == min(Qmax , max(0 , Q_internal))\nバッテリ端子電圧（バッテリ出力電圧は、バッテリ内部抵抗、電流によりバッテリ開路電圧から変化）\nVb == OCV - R*Ib\nバッテリ端子電位差\nVb == p.v - n.v\nバッテリ充電率\nSOC == Q_current / Qmax *100\n45\nJMAAB Plant Model Workshop 6\n（４）Simscape コード\ncomponent Battery\n% Simple Battery\n% Ver. 1.0  Jun/22, 2017  JMA",
