      "text": "nt Model Workshop 6\n（４）Simscape コード\ncomponent Battery\n% Simple Battery\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nparameters\nSOC_init = { 60    , '1'   };   % Initial SOC [%]\nQmax     = { 7*3600, 'A*s' };   % Max Capacity\nR        = { 0.1   , 'Ohm' };   % Internal Resisitance\nend\ninputs\n% Battery Open Circuit Voltage (OCV)\nOCV = { 0, 'V' };   % OCV [V] : left\nend\noutputs\nSOC = { 0, '1' };   % SOC [%] : right\nend\nnodes\np = foundation.electrical.electrical;   % + : right\nn = foundation.electrical.electrical;   % - : right\nend\nvariables\nIb         = { 0, 'A'   };  % Current\nVb         = { 0, 'V'   };  % Voltage\nQ_internal = { 0, 'A*s' };  % Electric Charge (Internal)\nQ_current  = { 0, 'A*s' };  % Electric Charge\nend\nfunction setup\nQ_internal = SOC_init / 100 * Qmax; % Q_in initia",
