      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 55,
      "text": "今回、Simulink で準備したコントローラモデルは、あらかじめ設定した目標車速に車両モデルが追従するようにドライバー\nモデルからアクセルペダル開度が指示され、そのアクセル開度に基づき簡易的に HEV パワートレーンのトルクおよびバッテリー充電\n量を制御するため、プラントモデルに以下の要求を行う。尚、あくまでサンプルの簡易的なコントローラモデルであり、現実に沿ってい\nない点や十分な動作検証がされていないことをご理解いただきたい。\n・ギヤ変速指示\n・走行時エンジントルク、モータトルク分配、要求\n・減速時モータ回生トルク要求\n・ジェネレータトルク要求\n(1) モデル概要\nFig.3-24  HEV 制御モデル概要\n47\nJMAAB Plant Model Workshop 6\n（２）接続例\nJMAAB プラントモデリングガイドラインでは、コントローラモデルは各コンポーネントの階層に配置することが推奨されているが、階\n層が深くなるデメリットがあり、現在のプラントモデル WS で議論した結果、目的に応じて使い分けることも必要との結論に達してい\nるため、今回は階層が深くならず可読性が良い以下の方式を選択した。\nFig.3-26  HEV 制御モデル 接続例\nFig.3-25  HEV 制御モデル\n48\nJMAAB Plant Model Workshop 6\n（３）モデル詳細\n（３－１）PT System Torque Controller\n設定した最大トルクにドライバアクセル開度の比率に乗じて、ドライバ要求トルクを算出し、エンジンとモータに走行に必要なトル\nクを配分する。配分比率は１：１としているが、バッテリー充電率が低くなった場合は、モーターアシストを停止し、エンジンのみで\n走行する。尚、EV 走行は考慮していない。\n（３－２）Battery Management\nバッテリー充",
