      "chunk_index": 56,
      "text": "：１としているが、バッテリー充電率が低くなった場合は、モーターアシストを停止し、エンジンのみで\n走行する。尚、EV 走行は考慮していない。\n（３－２）Battery Management\nバッテリー充電率が 70％未満の場合、発電モータが一定トルクで発電し、70％以上の場合は過充電防止のため、発電モー\nタトルクを 0 にする。また、バッテリー充電率が低い場合（5％未満）走行モータへの要求トルクを 0 にする。\nFig.3-27  PT System Torque Controller モデル\nFig.3-28  Battery Management モデル\n49\nJMAAB Plant Model Workshop 6\n（３－3）Engine Controller\n走行に必要なトルクとバッテリー充電に必要なトルクを合算し、あらかじめ設定した最大エンジントルクの範囲内でエンジン要求\nトルクを出力する。\n（３－4）Motor Controller\nブレーキペダルが踏まれていない場合かつアクセルペダルが踏まれている場合は、走行トルクとして配分されたトルクを要求する。\nブレーキペダルが踏まれた場合は、ペダル開度と現在の車速からモータの減速トルクを算出し要求する。\nFig.3-29  Engine Controller モデル\nFig.3-30  Motor Controller モデル\n50\nJMAAB Plant Model Workshop 6\n（３－5）Generator Controller\nアクセルペダルが踏まれている場合のみ、発電トルクを要求する。\n（３－6）T/M Controller\nアクセルペダルとトランスミッション出口のアクスル回転数から、ギアポジションを選択し、要求ギヤを決定する。\nFig.3-31  Generator Controller モデル\nFig.",
