      "text": "troller\nアクセルペダルとトランスミッション出口のアクスル回転数から、ギアポジションを選択し、要求ギヤを決定する。\nFig.3-31  Generator Controller モデル\nFig.3-32  T/M Controller モデル\n51\nJMAAB Plant Model Workshop 6\n3.4  評価\nここでは、パワートレーンモデルにおいてトルク、ギヤ段などが正常に動作し、代表的な台上試験モード（１０－１５モード）\nの目標車速に車両が追従しているかどうか、またバッテリ充電率をシミュレーションにより検証した。尚、車体のモデルは、次の章で\n説明される車両運動モデルと接続して車速をシミュレーションしたが、ドライバーモデルは、アクセルペダルとブレーキペダルの操作の\nみ実行し、ステアリング操作は行っていない。\n(1) 車速追従性\n目標車速に対して、シミュレーションされた車速は問題なく追従している。\nFig.3-33  シミュレーション結果  その１\n52\nJMAAB Plant Model Workshop 6\n(2) トルク制御とバッテリー充電率の推移\nバッテリーSOC は、発電用モータが動作することにより上昇、かつ 70％を超えると発電モータトルクは使用を制限する。\n一方、減速時は走行用モータが回生しており、これによってもバッテリーSOC は上昇していることがわかる。エンジントルクは、車\n両走行分と発電モータ分の合算分が出力されており、プラントモデルは、当初の目論見どおり意図通り動作していることがわかる。\nFig.3-34  シミュレーション結果  その２\n53\nJMAAB Plant Model Workshop 6\n54\nJMAAB Plant Model Workshop 6\n4 車両運動モデル\n4.1 目的\n本章では、車両平面運動モデルを題材に、",
