      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 58,
      "text": "53\nJMAAB Plant Model Workshop 6\n54\nJMAAB Plant Model Workshop 6\n4 車両運動モデル\n4.1 目的\n本章では、車両平面運動モデルを題材に、Simscape カスタムドメインの作成、および、車両としての挙動を視覚的に確認す\nるためのモデルの作成方法について紹介する。\n4.2 構成\nここで取り扱う車両運動モデルは、タイヤ、車体、ステアリング、ブレーキ から構成される。\n【タイヤ】\n四輪独立に車軸周りに回転するものとし、前輪はディファレンシャルギアとつながっており、トルクと回転数の授受を行う。舵角は\n前輪の左右に等しい値をステアリングから入力する。その他は車体とやりとりする。\n【車体】\nタイヤとのみ力・トルクと速度・角速度をやり取りする。\n【ステアリング】\nステアリングの舵角に応じ、ギア比からタイヤ実舵角を決める。\n【ブレーキ】\n摩擦を模擬して回転数が 0 となるよう一定トルクを与え、0 となったあとは回転しないよう必要なトルクを与える。\nFig.4-1  車両運動モデル構成\n55\nJMAAB Plant Model Workshop 6\n4.3 部品モデル\n4.3.1 タイヤ\n本書ではタイヤは車軸周りの回転と舵角に応じた回転を行い、それ以外の自由度はなく車体に固定されているものとする。\nタイヤはデフと車軸周りのトルクと角速度をやり取りする。またタイヤと車体は平面並進方向の力・接地点周りの力のモーメント\nをやりとりする。入力としてタイヤへの実舵角と接地反力を受け入れる。\nここでは演算が簡便でありかつ実用性のある λ-Method タイヤを用いた。\n（１）λ-Method タイヤ[4-1]\nスリップ率をベクトルとして扱い、Fig4-3 のように、ベクトルλの方向にタイヤ力が発生すると考える手法となる。\nFig.4-2",
