      "chunk_index": 59,
      "text": "hod タイヤを用いた。\n（１）λ-Method タイヤ[4-1]\nスリップ率をベクトルとして扱い、Fig4-3 のように、ベクトルλの方向にタイヤ力が発生すると考える手法となる。\nFig.4-2  車両運動モデルの座標系とその関係\nFig.4-3  λ-Method タイヤモデル座標系\n56\nJMAAB Plant Model Workshop 6\nスリップ率ベクトル 𝝀⃗\nタイヤ回転各速度を速度に換算したベクトル 𝑉𝜛⃗⃗⃗⃗  、 車両速度ベクトル 𝑉⃗ 、から、スリップ率ベクトル 𝝀⃗  が求まる。\n𝜆 = 𝑉𝜛⃗⃗⃗⃗ − 𝑉⃗\nmax (|𝑉⃗ |,|𝑉𝜛⃗⃗⃗⃗ |)\nここで、 𝑉𝜛⃗⃗⃗⃗  はタイヤ回転各速度を速度に換算したベクトル、𝑉⃗  は車両速度ベクトルとなる。\nタイヤの発生する力ベクトル 𝒇⃗\n𝑓 =  𝜇(|𝜆|)𝑀𝑔 𝜆\n|𝜆|\nここで、 𝜇(|𝜆|) はスリップ率から換算可能なタイヤと路面摩擦係数関数、𝑀𝑔 は動的な垂直荷重となる。ここで、 |𝜆| は、\n以下となる。\n|𝜆| = √𝜆𝑥2 + 𝜆𝑦2\nまた、 𝜆𝑥 、𝜆𝑦 は、上記スリップ率ベクトル 𝝀⃗  より、以下と表せる。\n𝜆𝑥 = 𝑉𝜛 − 𝑉𝑐𝑜𝑠(𝛿)\nmax(|𝑉|,|𝑉𝜛|)\n𝜆𝑦 = −𝑉𝑠𝑖𝑛(𝛿)\nmax (|𝑉|,|𝑉𝜛|)\n次に、路面摩擦係数関数 𝜇(|𝜆|) から、前後方向の摩擦係数 𝜇𝑥 、横方向の摩擦係数 𝜇𝑦 は、∠𝜆  を用いて次のよう表\nされる。\n𝜇𝑥 =  𝜇(|𝜆|)sin (∠𝜆 )\n𝜇𝑦 =  𝜇(|𝜆|)cos (∠𝜆 )\n尚 ∠𝜆  は、以下と表される。\n∠𝜆  =  arctan (𝜆𝑥\n𝜆𝑦\n)\n上記の各式からタイヤ力を演算する。求めたタイヤ力は、タイヤ固定座標系 (x,y) を基準としているため、車両固定座標系\n(X, Y) に変換する",
