      "chunk_index": 60,
      "text": "される。\n∠𝜆  =  arctan (𝜆𝑥\n𝜆𝑦\n)\n上記の各式からタイヤ力を演算する。求めたタイヤ力は、タイヤ固定座標系 (x,y) を基準としているため、車両固定座標系\n(X, Y) に変換する。\n[𝐹𝑋\n𝐹𝑌\n] = [cos(𝛿) −sin(𝛿)\nsin(𝛿) cos(𝛿) ] [𝑓𝑥\n𝑓𝑦\n].\n尚、Fig4-3 は前輪におけるタイヤ回転方向を x 軸とした場合の、車両座標系の概念図である。δ は、タイヤの実舵角とな\nる。\n57\nJMAAB Plant Model Workshop 6\n（１）モデルブロック\n（２）接続例\nFig.4-5  λ-Method タイヤブロック 接続例\nFig.4-4  λ-Method タイヤブロック\n58\nJMAAB Plant Model Workshop 6\n（３）モデル詳細\n名称 Lambda-Method Tire\n概要 トルク/力の向き：ディファレンシャルギアからのトルク入力が正, タイヤから車両に対する出力トルク・力方向が正\n計算内容：\n① タイヤ角速度, 車両速度 及び タイヤ舵角から、タイヤ固定座標系に対する x,y 方向のスリップ率を計算\n② 上記 ① の計算結果の絶対値、及び、そのなす角を計算\n③ 上記 ② の演算結果より、タイヤ-路面間摩擦を計算\n④ タイヤ固定座標系に対する、x, y 軸報告のタイヤが発生する力を計算\n⑤ 車両固定座標系に変換\nノード   ポート名 物理ドメイ\nン\nThrough/Across 内容 表示位置\n1 A 機械(回\n転)\n回転数[rad/s]、トルク\n[N*m]\n駆動トルクのやり\n取り\nleft\n2 P カスタム 力[N]、速度[m/s]/回\n転数[rad/s]、\n車両との物理量の\nやり取り\nright\n3 S カスタム トルク(Nm)、回転数\n(rad/s)\nステアリングとの物",
