      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 63,
      "text": "）Simscape コード\ncomponent lambda_method_tire\n% Lambda-Method Tire\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nnodes\nA = foundation.mechanical.rotational.rotational;   % A:left\nP = PMWS_Simscape_Library.Chassis.PlaneMotion;    % P:right\nS = PMWS_Simscape_Library.Chassis.custom_rotation % S:left\nend\ninputs\nFz    = { 1.0 , 'N' }; % Fz        :right\nend\nvariables\nV_X   = { 0.0, 'm/s' };\nV_Y   = { 0.0, 'm/s' };\nV     = { 0.0, 'm/s' };\nV_omega   = { 0.0, 'm/s' };\nmaxV  = { 0.001, 'm/s' };\ndelta = { 0 , 'rad' };\nlambda    = { 0.0, '1' };\nlambda_x  = { 0.0, '1' };\nabs_lambda_x  = { 0.0, '1' };\nlambda_y  = { 0.0, '1' };\nabs_lambda_y  = { 0.0, '1' };\nlambda_angle = { 0.0, 'rad' };\nmu        = { 0.0, '1' };\nmu_x      = { 0.0, '1' };\nmu_y      = { 0.0, '1' };\nf_x        = { 0.0, 'N' };\nf_y",
