      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 67,
      "text": "𝑃3𝑥𝐹𝑦3 − 𝑃3𝑦𝐹𝑥3 + 𝑃4𝑥𝐹𝑦4 − 𝑃4𝑦𝐹𝑥4 − 𝐷3𝜔.\nFig.4-6  車体モデル概要\n65\nJMAAB Plant Model Workshop 6\n車両座標系の速度を絶対座標系に変換\n𝑣𝑥 𝑤𝑐𝑠 = 𝑣𝑥 cos𝜃𝑦𝑎𝑤 − 𝑣𝑦 sin𝜃𝑦𝑎𝑤,\n𝑣𝑦 𝑤𝑐𝑠 = 𝑣𝑦 sin𝜃𝑦𝑎𝑤 + 𝑣𝑥 cos𝜃𝑦𝑎𝑤,\n𝑑\n𝑑𝑡𝜃𝑦𝑎𝑤 = 𝜔.\nここで、𝑣𝑥 𝑤𝑐𝑠、𝑣𝑦 𝑤𝑐𝑠はそれぞれ絶対座標系での x、y 方向の速度、𝜃𝑦𝑎𝑤はヨー角。\n絶対座標での車両位置 𝑥𝑤𝑐𝑠、𝑦𝑤𝑐𝑠の計算\n𝑑\n𝑑𝑡𝑥𝑤𝑐𝑠 = 𝑣𝑥 𝑤𝑐𝑠,\n𝑑\n𝑑𝑡𝑦𝑤𝑐𝑠 = 𝑣𝑦 𝑤𝑐𝑠.\n（１）モデルブロック\nFig.4-7  車体モデルブロック\n66\nJMAAB Plant Model Workshop 6\n（２）接続例\n（３）モデル詳細\n名称 3DoF Vehicle\n概要 3 自由度の簡易車両モデル\nトルク、力の向き：すべてのポートで外から内が正\n計算内容：\n① 入力された風速と車速から空気抵抗を計算\n② 各タイヤから入力される力と空気抵抗から車両の加速度を計算\n③ 各タイヤから入力される力と重心位置からｚ軸周り(ヨー方向)の角速度を計算\n④ 車速とｚ軸周りの角速度から各タイヤの速度を計算\n⑤ 車速(車両座標系)やヨー角を使って絶対座標系の車速と位置を計算\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 RR ２自由度並\n進\nカスタム\nX 軸並進力[N]、Y 軸\n並進力[N]\nX 軸速度[m/s]、Y 軸\n速度[m/s]\nタイヤとの物理\n量のやり取り\nbottom\n2 FR ２自由度並\n進\nカスタム\nX 軸並進力[N]、Y 軸\n並進力[N]\nX 軸速度[m/s]、Y 軸\n速度[m/s]\nタイヤとの物理\n量のやり取り\nbo",
