      "text": "内容 範囲 初期設定値 単位\n1 m 車重 - 1500 kg/s\n2 g 重力加速度 - 9.81 m/s^2\n3 I Z 軸周りの\n慣性モーメン\nト\n- 2.00E+03 kg*m^2\n4 lf 重心からフロ\nント\n車軸までの距\n離\n- 1.8 m\n68\nJMAAB Plant Model Workshop 6\n5 lr 重心からリア\n車軸までの距\n離\n- 2.4 m\n6 wrl 重心から左右\nの\n車両端までの\n距離\n- 1 m\n7 Af 車両前面の\n面積\n- 3 m^2\n8 Cd 空気の抵抗\n係数\n- 0.4 -\n9 rho 空気の密度 - 1.2 kg/m^3\n10 D_2 Y 方向の車\n速に比例した\n抵抗の係数\n- 0.01 kg/s\n12 D_3 Z 軸周りの\n回転数に比\n例した抵抗の\n係数\n- 0.01 N*m*s\n変数   変数名 内容 範囲 初期値 単位\n1 Fx1 右フロントタイ\nヤから受ける\nX 方向の力\n- 0 N\n2 Fx2 左フロントタイ\nヤから受ける\nX 方向の力\n- 0 N\n3 Fx3 左リアタイヤか\nら受ける X 方\n向の力\n- 0 N\n4 Fx4 右リアタイヤか\nら受ける X 方\n向の力\n- 0 N\n5 Fy1 右フロントタイ\nヤから受ける\nY 方向の力\n- 0 N\n6 Fy2 左フロントタイ\nヤから受ける\nY 方向の力\n- 0 N\n69\nJMAAB Plant Model Workshop 6\n7 Fy3 左リアタイヤか\nら受ける Y 方\n向の力\n- 0 N\n8 Fy4 右リアタイヤか\nら受ける Y 方\n向の力\n- 0 N\n9 Mz ヨー方向に回\n転させようとす\nるトルク\n- 0 N*m\n10 Omega ヨー方向の角\n速度\n- 0 rad/s\n11 Px1 車両座標系\nでの右フロント\nタイヤの X 座\n標\n- 1 m\n12 Px2",
