      "text": "座標系\nでの\n車速の Y 成\n分\n- 0 m/s\n29 yaw ヨー角 - 0 rad\n方程式、その他\n車両座標系でのタイヤの X 座標\nPx1 = lf\nPx2 = lf\nPx3 = -lr\nPx4 = -lr\n71\nJMAAB Plant Model Workshop 6\n車両座標系でのタイヤの Y 座標\nPy1 = -wrl\nPy2 = wrl\nPy3 = wrl\nPy4 = -wrl\n車両重心からタイヤまでの距離\nOP1 = sqrt(Px1^2+Py1^2)\nOP2 = sqrt(Px2^2+Py2^2)\nOP3 = sqrt(Px3^2+Py3^2)\nOP4 = sqrt(Px4^2+Py4^2)\n車両座標系での各タイヤの位置を示す角度\nphi1 = atan(Py1/Px1)\nphi2 = atan(Py2/Px2)\nphi3 = atan(Py3/Px3)\nphi4 = atan(Py4/Px4)\n運動方程式\nm * (dvx(t)/dt - Omega(t) * vy(t)) = Fx1(t) + Fx2(t) + Fx3(t) + Fx4(t) + Fd(t)\nFd(t) = (1/2) * Cd * rho * Af * (vx(t) - W(t))^2 * sign(vx(t) - W(t))\nm * (dvy(t)/dt + Omega(t) * vx(t)) = Fy1(t) + Fy2(t) + Fy3(t) + Fy4(t) + D_2 * vy(t)\nI * dOmega(t)/dt = Mz(t)\nMz(t) = Px1*Fy1(t) - Py1*Fx1(t) + Px2*Fy2(t) - Py2*Fx2(t) + Px3*Fy3(t) - Py3*Fx3(t) +\nPx4*Fy4(t) - Py4*Fx4(t) + D_3*Omega(",
