      "text": "assis.PlaneMotion;   % FR:bottom\nend\noutputs\nT1_Fz = { 1.0 , 'N' };                             % FR_Fz:bottom\nend\n73\nJMAAB Plant Model Workshop 6\nvariables\nFx1  = { 0.0, 'N'   };\nFx2  = { 0.0, 'N'   };\nFx3  = { 0.0, 'N'   };\nFx4  = { 0.0, 'N'   };\nFy1  = { 0.0, 'N'   };\nFy2  = { 0.0, 'N'   };\nFy3  = { 0.0, 'N'   };\nFy4  = { 0.0, 'N'   };\nMz   = { 0.0, 'N*m' };\nOmega = { 0.0, 'rad/s' };\nPx1  = { 1.0, 'm'   };\nPx2  = { 1.0, 'm'   };\nPx3  = { 1.0, 'm'   };\nPx4  = { 1.0, 'm'   };\nPy1  = { 1.0, 'm'   };\nPy2  = { 1.0, 'm'   };\nPy3  = { 1.0, 'm'   };\nPy4  = { 1.0, 'm'   };\nOP1  = { 1.0, 'm'   };\nOP2  = { 1.0, 'm'   };\nOP3  = { 1.0, 'm'   };\nOP4  = { 1.0, 'm'   };\nphi1 = { 0.0, 'rad' };\nphi2 = { 0.0, 'rad' };\nphi3 = { 0.0, 'rad' };\nphi4 = { 0.0, 'rad' };\nvx_wcs = { 0.0, 'm/s'   };\nvy_wcs = { 0.0,",
