      "text": "= { 0.0, 'm'   };   % X:bottom\ny_wcs   = { 0.0, 'm'   };   % Y:bottom\nend\ninputs\nW = { 0  'm/s' };  % W : top\nend\noutputs %%Drag force\nFd  = { 0  'N'   };  % Fd:bottom\nend\nbranches\nFx1 : T1.Fx -> *;\nFy1 : T1.Fy -> *;\nFx2 : T2.Fx -> *;\nFy2 : T2.Fy -> *;\nFx3 : T3.Fx -> *;\nFy3 : T3.Fy -> *;\nFx4 : T4.Fx -> *;\nFy4 : T4.Fy -> *;\nend\n74\nJMAAB Plant Model Workshop 6\nequations\nPx1 == lf;\nPx2 == lf;\nPx3 == -lr;\nPx4 == -lr;\nPy1 == -wrl;\nPy2 == wrl;\nPy3 == wrl;\nPy4 == -wrl;\nOP1 == sqrt(Px1^2+Py1^2);\nOP2 == sqrt(Px2^2+Py2^2);\nOP3 == sqrt(Px3^2+Py3^2);\nOP4 == sqrt(Px4^2+Py4^2);\nphi1 == atan(Py1/Px1);\nphi2 == atan(Py2/Px2);\nphi3 == atan(Py3/Px3)+pi;\nphi4 == atan(Py4/Px4)+pi;\nFd == (1/2)*Cd*rho*Af*(vx-W)^2*sign(vx-W);\nm*(vx.der-Omega*vy) == Fx1+Fx2+Fx3+Fx4 ...\n- Fd ;\nm*(vy.der+Omega*vx) == Fy1+Fy2+Fy3+F",
