      "text": "2*sign(vx-W);\nm*(vx.der-Omega*vy) == Fx1+Fx2+Fx3+Fx4 ...\n- Fd ;\nm*(vy.der+Omega*vx) == Fy1+Fy2+Fy3+Fy4 - D_2 * vy;\nI*Omega.der == Mz;\nMz == Px1*Fy1-Py1*Fx1 + Px2*Fy2-Py2*Fx2 ...\n+ Px3*Fy3-Py3*Fx3 + Px4*Fy4-Py4*Fx4 - D_3 * Omega  ;\nT1.Vx  == vx - OP1*Omega*sin(phi1);\nT1.Vy  == vy + OP1*Omega*cos(phi1);\nT1_Fz  == m*g/4.0;\nT2.Vx  == vx - OP2*Omega*sin(phi2);\nT2.Vy  == vy + OP2*Omega*cos(phi2);\nT2_Fz  == m*g/4.0;\n75\nJMAAB Plant Model Workshop 6\nT3.Vx  == vx - OP3*Omega*sin(phi3);\nT3.Vy  == vy + OP3*Omega*cos(phi3);\nT3_Fz  == m*g/4.0;\nT4.Vx  == vx - OP4*Omega*sin(phi4);\nT4.Vy  == vy + OP4*Omega*cos(phi4);\nT4_Fz  == m*g/4.0;\n%速度を絶対座標系の速度に変換。\nyaw.der == Omega;\nvx_wcs == vx * cos(yaw) - vy * sin(yaw);\nvy_wcs == vx * sin(yaw) + vy * cos(yaw);\n%位置の微分が速度\nx_wcs.der == vx_wcs;\ny_wcs.der == vy_wcs;\nend",
