      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 78,
      "text": ");\nvy_wcs == vx * sin(yaw) + vy * cos(yaw);\n%位置の微分が速度\nx_wcs.der == vx_wcs;\ny_wcs.der == vy_wcs;\nend\nend\n76\nJMAAB Plant Model Workshop 6\n4.3.4 ステアリング\nステアリングモデルは、シンプルなモデルとして表現した。\nタイヤ実舵角は、次式に示すように、ハンドル舵角に対しトータルのギア比を乗算することで一意に求まるようなモデルとなってい\nる。したがって、ステアリング-タイヤ間のダイナミクスは考慮していない。\n𝜹𝑇𝑖𝑟𝑒 𝐴𝑛𝑔𝑙𝑒  = 𝑮𝑇𝑜𝑡𝑎𝑙 𝐺𝑒𝑎𝑟 𝑅𝑎𝑡𝑖𝑜 ∙ 𝜽𝑆𝑡𝑒𝑒𝑟𝑖𝑛𝑔 𝐴𝑛𝑔𝑙𝑒\n（１）モデルブロック\n（２）接続例\nFig.4-9  ステアリングブロック\nFig.4-10  ステアリングブロック 接続例\n77\nJMAAB Plant Model Workshop 6\n（３）モデル詳細\n名称 Steering\n概要 シンプルなステアリング\nステアリングの舵角に応じ、ギア比からタイヤ実舵角を求める。\n(ダイナミクスは考慮していない)\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 S_L 機械回転 トルク(Nm), 回転(rad) 回転角度 right\n2 S_R 機械回転   回転角度 right\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 Steering\nAngle\nステアリング\n舵角\n━ 0 rad left\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 Gear Ratio ステアリング\n機構内のトー\nタルギア比\n━   1/16 ━\n変数   変数名 内容 範囲 初期値 単位\n1 Mz_L ━ ━ 0 N*m\n2 Mz_R ━ ━ 0",
