      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 79,
      "text": "単位\n1 Gear Ratio ステアリング\n機構内のトー\nタルギア比\n━   1/16 ━\n変数   変数名 内容 範囲 初期値 単位\n1 Mz_L ━ ━ 0 N*m\n2 Mz_R ━ ━ 0 N*m\n方程式、その他\nステアリングの舵角とタイヤの舵角関係式\nTireAngle = TotalGearRatio ・ SteeringAngle\n78\nJMAAB Plant Model Workshop 6\n（４）Simscape コード\ncomponent Steering\n% Simple Steering\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Model ing Workshop\ninputs\ndelta_H = { 0, 'rad' }; % Steering Angle : left\nend\nnodes\nS_L = PMWS_Simscape_Library.Chassis.custom_rotation % S_L:right\nS_R = PMWS_Simscape_Library.Chassis.custom_rotation % S_R:right\nend\nparameters\nratio = { 1/16, '1' }; % Gear ratio\nend\nvariables\nMz_L    = { 0.0, 'N*m' };\nMz_R    = { 0.0, 'N*m' };\nend\nbranches\nMz_L   : S_L.Mz -> *;\nMz_R   : S_R.Mz -> *;\nend\nequations\nS_L.delta ==  ratio * delta_H;\nS_R.delta ==  ratio * delta_H;\nend\nend\n79\nJMAAB Plant Model Workshop 6",
