      "text": "L.delta ==  ratio * delta_H;\nS_R.delta ==  ratio * delta_H;\nend\nend\n79\nJMAAB Plant Model Workshop 6\n4.3.5 ブレーキ\n本節では、車両モデル内で使用するブレーキモデルについて説明する。\nまず、ブレーキ状態の判定条件は下図とする。入力 𝜔 と 𝐹𝐵 に対し、閾値 𝜔_𝑡ℎ𝑟 と 𝐹𝐵_𝑡ℎ𝑟 によって、Locked state,\nPositive unlock state, Negative unlock state に分かれる。\nPositive unlock state の場合は、下記式でブレーキトルクを計算する。\n𝜏𝑘 = −μ ×𝑟𝑒𝑓𝑓 × 𝐹𝐵\n一方、Negative unlock state の場合は、下記式となる。\n𝜏𝑘 =  μ ×𝑟𝑒𝑓𝑓 × 𝐹𝐵\nここで、𝜏𝑘[Nm] は、ブレーキトルクを表し、ブレーキバッドにかかる力 𝐹𝐵[𝑁] に比例する。μ[−] は動摩擦係数、𝑟𝑒𝑓𝑓[𝑚] は\n有効半径である。\nUnlock state の場合、回転方向と逆に摩擦力によるブレーキトルクがかかる。しかし、𝐹𝐵 が十分大きくかつ相対回転 𝜔 が\n0 になると、2 つの剛体は結合し、１ つの剛体として振る舞う。このとき、物理方程式は、２つの運動方程式が１つの運動方\n程式となるが、Simscape ではシミュレーション中に方程式の数を変えることはできないため、何らかの近似が必要となる。本入\n門書では、近似の方法として、以下の方法を行った。\nFig.4-11  ブレーキ状態判定\n𝐹𝐵[𝑁]\n𝜔[𝑟𝑎𝑑/𝑠]\n+𝜔_𝑡ℎ𝑟\n𝐹𝐵_𝑡ℎ𝑟\n−𝜔_𝑡ℎ𝑟\nPositive\nunlock state\n(state = 1 )\nNegative\nunlock state\n(stat",
