      "text": "定\n𝐹𝐵[𝑁]\n𝜔[𝑟𝑎𝑑/𝑠]\n+𝜔_𝑡ℎ𝑟\n𝐹𝐵_𝑡ℎ𝑟\n−𝜔_𝑡ℎ𝑟\nPositive\nunlock state\n(state = 1 )\nNegative\nunlock state\n(state = -1 )\n0\nLocked  state\n(state = 0)\n80\nJMAAB Plant Model Workshop 6\n𝜏𝑘 = −μ ×𝑟𝑒𝑓𝑓 × 𝐹𝐵× 𝜔\n𝜔_𝑡ℎ𝑟 × exp ( 𝑇𝐿\n∆𝑇)\nここで、TL は Locked state の継続時間、∆T は半減期である。\n（１）モデルブロック\n（２）接続例\nFig.4-12  ブレーキブロック\nFig.4-13  ブレーキブロック (接続例)\n81\nJMAAB Plant Model Workshop 6\n（３）モデル詳細\n名称 Brake\n概要 3 自由度の簡易車両モデル\nトルクの向き：外から内が正\n計算内容：\n① 入力された圧着力から制動トルクを計算\n② ブレーキの状態を判定し、制動力の値を決定(開放状態：0[N*m]、ロック状態は指数関数的に減衰)\nノード   ポート名 物理ドメイン Through/Across 内容 表示位置\n1 Tire 機械(回転) 回転数[rad/s]、\nトルク[N*m]\nタイヤと制動トル\nクのやり取り\nright\n入力   ポート名 内容 範囲 初期値 単位 表示位置\n1 state 状態(ロック、\nアンロックな\nど)\n- 0 - left\n2 Brake_force 圧着力 - 0 N left\n3 Lock_time ロック状態の\n継続時間\n- 0 s left\n出力   ポート名 内容 範囲 初期値 単位 表示位置\n1 w_out タイヤの回転\n数\n- 0 rad/s right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 w_thr ロ",
