      "text": "出力   ポート名 内容 範囲 初期値 単位 表示位置\n1 w_out タイヤの回転\n数\n- 0 rad/s right\nパラメータ   パラメータ名 内容 範囲 初期設定値 単位\n1 w_thr ロックとアンロ\nック状態の回\n転数の閾値\n- 3 rad/s\n2 T_L ロック状態時\nのトルク減衰\nの半減期\n- 1 s\n3 uk 動摩擦係数 - 1 -\n4 Er 有効半径 - 1 m\n5 eps 条件判定用\nの微小値\n- 0.1 -\n変数   変数名 内容 範囲 初期値 単位\n1 w_T タイヤの回転\n数\n- 0 rad/s\n2 t_F 制動トルク\n(状態考慮\n前)\n- 0 N*m\n3 t_T 制動トルク - 0 N*m\n4 state 状態 - 0 -\n82\nJMAAB Plant Model Workshop 6\n方程式、その他\n圧着力から制動トルクを計算\nt_F = -uk * Er * Brake_force\n状態を考慮し、制動トルクを決定する\nif アンロック状態で順回転\nt_T = T_F\nelse if アンロック状態で逆回転\nt_T = -t_F\nelse if ロック状態\nt_T = t_F / w*thr * w_T * exp(L_time / T_L)\nelse (開放状態)\nt_T = 0\n83\nJMAAB Plant Model Workshop 6\n（４）Simscape コード\ncomponent Brake\n% Brake\n% Ver. 1.0  Jun/22, 2017  JMAAB Plant Modeling Workshop\nnodes\nTire = foundation.mechanical.rotational.rotational; % Tire:right\nend\ninputs\nstate_in ={ 0, '1' }; %",
