      "text": "t Model Workshop 6\nbranches\nt_T : * -> Tire.t;\nend\nequations\nw_T ==  Tire.w;\nstate==state_in;\nt_F ==  -uk * Er * Brake_force ;\n%% Positive Unlock state\nif( lt(abs(state-1),eps ))\nt_T == t_F;\n%% Negative Unlock state\nelseif( lt(abs(state + 1),eps ))\nt_T == -t_F;\n%% Lock state\nelseif( lt(abs(state),eps ))\nt_T == t_F/w_thr * w_T * exp(L_time /T_L );\nelse\nt_T == 0.0;\nend\nw_out == w_T ;\nend\nend\n85\nJMAAB Plant Model Workshop 6\n4.4 評価\nここでは、一定の車速と一定の舵角で旋回させた時(定常円旋回)の軌跡を理論値と比較することで、モデルの評価を行った。\n検証を簡単に行うために、過渡状態ではなく定常状態のシミュレーションで評価とした。\n定常円旋回の半径を求める理論式は、自動車の運動と制御[4-2]を参考に導出した。\n定常円旋回時の車両の速度 V と角速度𝜔、旋回半径 r の関係は、\n𝑟 = 𝑉\n𝜔.\n車両横方向の力のつりあいは、自動車の運動と制御によると、各タイヤの横滑り角と実舵角が微小な場合、次のようにあらわ\nせる。\n𝑚𝑉𝜔 = 𝑌1 + 𝑌2 + 𝑌3 + 𝑌4.\nここで、m は車両の慣性質量、Yiは各タイヤに働くコーナリングフォースである。\n上記の 2 式より、定常円旋回時の旋回半径は、\n𝑟 = 𝑚𝑉2\n𝑌1 + 𝑌2 + 𝑌3 + 𝑌4\n.\n旋回半径の理論",
