      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 85,
      "text": "ここで、m は車両の慣性質量、Yiは各タイヤに働くコーナリングフォースである。\n上記の 2 式より、定常円旋回時の旋回半径は、\n𝑟 = 𝑚𝑉2\n𝑌1 + 𝑌2 + 𝑌3 + 𝑌4\n.\n旋回半径の理論値は、上記の式を用いて求めた。\n下記の手順で定常円旋回のシミュレーションを実施した。\n① 一定のトルク(前輪にそれぞれ 100[N*m])を入力し加速\n② 車速が一定になり定常円旋回\n③ 一定のトルク(前輪にそれぞれ 200[N*m])を入力し加速\n④ 車速が一定になり定常円旋回\nシミュレーション時の実舵角(タイヤの切れ角)は、2[deg]である。\n86\nJMAAB Plant Model Workshop 6\n表 4-1 定常円旋回時の旋回半径の比較\n定常円旋回時の軌跡を理論値とシミュレーション結果で比較を行ったものが Fig.4-14 と 表 4-1 である。\n理論値とシミュレーション結果の旋回半径がほぼ一致することが確認できた。\nFig.4-14  定常円旋回時の旋回半径の比較\n赤線：理論値\n青線：シミュレーション結果\n④200[N*m]時の\n定常円旋回の軌跡\n②100[N*m]時の\n定常円旋回の軌跡\n①100[N*m]で加速\n87\nJMAAB Plant Model Workshop 6\n【参考文献】\n[4-1] 堀内 泰 : 車両挙動安定化制御システムにおけるタイヤモデルの提案, 自動車技術会\n[4-2] 安部 正人 : 自動車の運動と制御 (車両運動力学の理論形成と応用),\n88\nJMAAB Plant Model Workshop 6\n5. Simscape Tips\n本章では、Simscape のモデリングからシミュレーション結果の確認までのひと通りの流れに関する情報を紹介する。\n5.1 Simscape モデルの作成\nここでは、Simscape モデル作成のた",
