      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 86,
      "text": "本章では、Simscape のモデリングからシミュレーション結果の確認までのひと通りの流れに関する情報を紹介する。\n5.1 Simscape モデルの作成\nここでは、Simscape モデル作成のための便利機能、端子接続に関する注意事項ついて説明する。なお、Simscape の新\n規モデル作成から結果表示までの流れが、下記 URL で確認できる。\nhttps://jp.mathworks.com/help/physmod/simscape/gs/essential-steps-for-constructing-a-physical-\nmodel.html\n5.1.1 モデル作成時の便利機能\nSimscape モデル作成時に、便利な機能を 2 つ紹介する。\n(1) ssc_new コマンド\nssc_new コマンドをコマンドウィンドウで実行すると、Simscape モデルをシミュレーションするのに必要な Solver\nConfiguration ブロックを含む新規モデルが起動する(Fig. 5-1 参照)。\nFig. 5-1  ssc_new コマンドを実行して開くモデル\n89\nJMAAB Plant Model Workshop 6\n(2) テンプレート機能\nR2015b 以降のバージョンでは、電気、機械（回転・並進）などのドメイン毎にテンプレートがある。Fig. 5-2 の\nSimulink アイコンをクリックして開く Simulink スタートページにて、主に使用するドメインのテンプレートが用意されている。使\n用するドメインのテンプレートを選択することで、リファレンスブロックを含む、Simscape モデルで必要なブロックを含むモデルが起\n動する。\n5.1.2 Simulink の端子と Simscape の端子の接続方法\nSimulink の端子と Simscape",
