      "chunk_index": 87,
      "text": "ックを含む、Simscape モデルで必要なブロックを含むモデルが起\n動する。\n5.1.2 Simulink の端子と Simscape の端子の接続方法\nSimulink の端子と Simscape の端子は直接接続できないため、変換が必要となる。Simulink の端子を Simscape\nに端子に接続するには Simulink-PS Converter ブロックを、Simscape 端子を Simulink に端子に接続するには PS-\nSimulink Converter ブロックを使用する。下記ドキュメントページで確認できる。\nhttps://jp.mathworks.com/help/physmod/simscape/ug/connecting-simscape-diagrams-to-simulink-\nsources-and-scopes.html\nFig. 5-2  Simulink テンプレート\n90\nJMAAB Plant Model Workshop 6\n5.1.3 カスタムコンポーネントの作成\nSimscape では、カスタムコンポーネントを作成することが可能である。下記に、本書で公開している情報を補足するための簡\n単な説明を行い、ドキュメントリンクを紹介する。\nカスタムコンポーネントを作成するための構文、概要、コンポーネントの一例など、下記 URL から参照可能となっている。\nhttp://www.mathworks.com/help/physmod/simscape/creating-custom-components.html\n次に、Simscape を使用するうえで重要な変数について紹介する。Simscape は、一般に言われている、非因果系モデリン\nグツールの１つである。コンポーネント間の接続を考える際に重要となるのが、下記の 2 つのタ",
