      "source_url": "file:///C:/Users/Kaoru/Documents/RAG_Engine/hils_rag_sample_docs/pdf/jmaab_plant_modeling_workshop_6.pdf",
      "title": "jmaab_plant_modeling_workshop_6",
      "file_type": "pdf",
      "chunk_index": 90,
      "text": "ながらサンプル時\n間を決定するアプローチが一般的である。下記 URL に、高速化のワークフローに関して記述されている。\nhttps://jp.mathworks.com/help/physmod/simscape/ug/real-time-model-preparation-workflow.html\n(2) ゼロクロッシング\nソルバーコンフィギュレーションの設定について、ゼロクロッシングの設定項目がある。ゼロクロッシングは、時間の経過に伴うシステ\nムの状態やダイナミクスの不連続な変化を表す。ゼロクロッシングを正確に特定することが、期待するシミュレーション結果を得るた\nめには重要である。まずは、ゼロクロッシングの設定を有効と設定することを推奨する。\n5.2.2 Solver Configuration ブロック\nSolver Configuration ブロックでは、Simscape 回路をシミュレーションするための設定を行う。設定の１つである、ローカ\nルソルバーは、Simscape 回路を離散化するか否かを決定する。まずは、OFF に設定し、連続として扱うことを推奨する。\n92\nJMAAB Plant Model Workshop 6\n5.3 シミュレーション結果の確認\nシミュレーション終了後、結果を確認する際の便利機能を紹介する。\n5.3.1 シミュレーション データのプロット\nSimscape 回路にある各ブロックのスルー変数、アクロス変数について、Fig. 5-4 のように、時刻歴応答が確認できる。\n確認するには、モデルのコンフィギュレーションパラメータの [Simscape] ペーンにある ‘Log simulation data’ を All に設\n定し、’Open viewer after simulation’ にチェックを入れてシミュレーションを行う。コン",
