      "text": "ape] ペーンにある ‘Log simulation data’ を All に設\n定し、’Open viewer after simulation’ にチェックを入れてシミュレーションを行う。コンフィギュレーションパラメータの設定を図\n解しているものが、下記のドキュメントページで確認できる。\nhttps://jp.mathworks.com/help/physmod/simscape/ug/log-and-plot-simulation-data.html\nまた、シミュレーション結果を確認する Simscape Result Explorer の使い方に関する説明は、下記のドキュメントページ\nで確認できる。\nhttps://jp.mathworks.com/help/physmod/simscape/ug/using-the-simscape-results-explorer.html\nFig. 5-4  Simscape Result Explorer\n93\nJMAAB Plant Model Workshop 6\n5.3.2 Probe ブロック\nMATLAB Central (ユーザーコミュニティサイト) にて、ブロック単体を接続して、手軽に応答を確認できる、Probe ブロックラ\nイブラリが公開されている。\n本ブロックは、下記 URL からダウンロードできる。\nhttp://jp.mathworks.com/matlabcentral/fileexchange/17969-simscape-probes\nFig. 5-5  Probe ブロック\n94\nJMAAB Plant Model Workshop 6\n5.4 変数の初期値の確認\nシミュレーション開始時に、初期化に関するエラーが出て、シミュレーションできないことがある。ここでは、Simscape モデルの初",
