      "file_type": "pptx",
      "chunk_index": 0,
      "text": "HILS Bench Bring-up Review\nsample deck for chunking / architecture / checklist / issue summary\nBench Topology\nHost PC\ndSPACE HIL\nVCU ECU\nBattery Sim\nポイント\n: ECU, plant, automation\nの境界が明示される資料は、\nRAG\nで\n'\nどこに責務があるか\n'\nを拾いやすい。\nMorning Bring-up Checklist\n1. PSU / rack / simulator power on\n2. model load and CANoe start\n3. IGN command and precharge monitor\n4. READY confirmation and torque inhibit check\n5. archive logs before next scenario\nOpen Issues\nID\nSymptom\nLikely layer\nStatus\nB-04\nPRECHARGE stall\nplant init\nopen\nB-08\ndiag timeout\ngateway\nwatch\nB-11\ntorque inhibit stuck\nVCU logic\ninvestigate",
